<?php require dirname(__DIR__).'/bootstrap.php';if(!empty($_SESSION['admin']))redirect('/admin/dashboard.php');if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$admin=$service->admins()->findByUsername(trim($_POST['username']??''));if($admin&&password_verify($_POST['password']??'',$admin['password_hash'])){session_regenerate_id(true);$_SESSION['admin']=['id'=>$admin['id'],'username'=>$admin['username']];redirect('/admin/dashboard.php');}$error='Invalid username or password.';} ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Login</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-dark d-flex align-items-center min-vh-100"><form class="card shadow p-4 mx-auto" style="width:360px" method="post"><h3>Admin login</h3><p class="text-muted">Student Portfolio CMS</p><?php if(!empty($error)):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><input type="hidden" name="csrf" value="<?=csrf()?>"><label class="form-label">Username</label><input class="form-control mb-3" required name="username"><label class="form-label">Password</label><input class="form-control mb-3" required type="password" name="password"><button class="btn btn-primary w-100">Sign in</button><a class="text-center small mt-3" href="/index.php">← Back to portfolio</a></form></body></html>
